mapper.select:
SELECT fd.fair_date_id, fd.operation_date, fd.capacity, fd.entry_start_time, fd.entry_end_time, COUNT(r.reservation_id) AS total_count, SUM(CASE WHEN r.status = 'CONFIRMED' THEN 1 ELSE 0 END) AS confirmed_count, SUM(CASE WHEN r.status = 'CHECKED_IN' THEN 1 ELSE 0 END) AS checked_in_count, SUM(CASE WHEN r.status = 'PENDING_PAYMENT' THEN 1 ELSE 0 END) AS pending_count, SUM(CASE WHEN r.status = 'CANCELED' THEN 1 ELSE 0 END) AS canceled_count, SUM(CASE WHEN r.status = 'EXPIRED' THEN 1 ELSE 0 END) AS expired_count, fd.capacity - SUM(CASE WHEN r.status IN ('PENDING_PAYMENT', 'CONFIRMED', 'CHECKED_IN') AND r.reservation_type != 'ONSITE_DIRECT' THEN 1 ELSE 0 END) AS remaining_capacity FROM fair_dates fd LEFT JOIN reservations r ON r.fair_id = fd.fair_id AND r.visit_date = fd.operation_date WHERE fd.fair_id = #{fairId}
AND fd.operation_date = #{date}
GROUP BY fd.fair_date_id, fd.operation_date, fd.capacity, fd.entry_start_time, fd.entry_end_time ORDER BY fd.operation_date ASC
